"""Version ranges, as written in manifests and in index dependencies (docs/ranges.md)."""

import re

from pinset.errors import RangeError
from pinset.version import BUILD_RE, PRERELEASE_RE, Version

OPERATORS = ("<=", ">=", "<", ">", "=", "^", "~")
WILDCARDS = ("x", "X", "*")
SPACES = " \t"
NUMBER_RE = re.compile(r"0|[1-9][0-9]*")
SPLIT_RE = re.compile(r"[ \t]+")
START = "0123456789xX*"


class _Comparator:
    """One bound. `names_pre` is set when the range text itself carries a prerelease on the version."""

    __slots__ = ("op", "version", "names_pre")

    def __init__(self, op, version, names_pre=False):
        self.op = op
        self.version = version
        self.names_pre = names_pre

    def test(self, v: Version) -> bool:
        b = self.op, self.version
        if self.op == "=":
            return v == self.version
        if self.op == "<":
            return v < self.version
        if self.op == "<=":
            return v <= self.version
        if self.op == ">":
            return v > self.version
        return v >= self.version


class _Alternative:
    def __init__(self, comparators, never=False):
        self.comparators = comparators
        self.never = never

    def test(self, v: Version) -> bool:
        if self.never:
            return False
        if not all(c.test(v) for c in self.comparators):
            return False
        if v.is_prerelease():
            return any(c.names_pre and c.version.release == v.release for c in self.comparators)
        return True


class Range:
    def __init__(self, text: str, alternatives, exact: bool):
        self.text = text
        self._alternatives = alternatives
        self._exact = exact

    def test(self, version: Version) -> bool:
        """True when `version` satisfies the range."""
        return any(a.test(version) for a in self._alternatives)

    def is_exact(self) -> bool:
        """True for a range that names one version (docs/ranges.md, section 10)."""
        return self._exact

    def __str__(self):
        return self.text


class _Partial:
    """A partial version: `nums` holds the leading numbers, a missing or wildcard part is absent."""

    def __init__(self, nums, pre=(), build=()):
        self.nums = nums
        self.pre = tuple(pre)
        self.build = tuple(build)

    @property
    def n(self):
        return len(self.nums)

    def full(self, fill=0) -> Version:
        nums = list(self.nums) + [fill] * (3 - self.n)
        return Version(*nums, self.pre, self.build)


def _bad_version(text, why):
    return RangeError("bad-version", f"{text!r}: {why}")


def _parse_partial(text: str) -> _Partial:
    core, plus, build = text.partition("+")
    if plus and not BUILD_RE.fullmatch(build):
        raise _bad_version(text, "invalid build metadata")
    core, dash, pre = core.partition("-")
    if dash and not PRERELEASE_RE.fullmatch(pre):
        raise _bad_version(text, "invalid prerelease")
    parts = core.split(".")
    if len(parts) > 3:
        raise _bad_version(text, "more than three parts")
    nums = []
    wild = False
    for part in parts:
        if part in WILDCARDS:
            wild = True
        elif NUMBER_RE.fullmatch(part):
            if wild:
                raise _bad_version(text, "a number after a wildcard")
            nums.append(int(part))
        else:
            raise _bad_version(text, f"invalid part {part!r}")
    if (dash or plus) and len(nums) != 3:
        raise _bad_version(text, "prerelease or build on a partial version")
    return _Partial(nums, pre.split(".") if dash else (), build.split(".") if plus else ())


def _zero(major, minor, patch):
    """`<major.minor.patch-0`: lower than every version of that release."""
    return _Comparator("<", Version(major, minor, patch, ("0",)))


def _ge(v: Version, names_pre=None):
    return _Comparator(">=", v, v.is_prerelease() if names_pre is None else names_pre)


def _block(p: _Partial):
    """Comparators for the block of versions a partial names."""
    if p.n == 0:
        return []
    if p.n == 1:
        return [_ge(Version(p.nums[0], 0, 0)), _zero(p.nums[0] + 1, 0, 0)]
    return [_ge(Version(p.nums[0], p.nums[1], 0)), _zero(p.nums[0], p.nums[1] + 1, 0)]


def _below(p: _Partial):
    """The bound `<` the whole block, and `<=` end of the block: (strictly below, up to and including)."""
    if p.n == 1:
        return _zero(p.nums[0], 0, 0), _zero(p.nums[0] + 1, 0, 0)
    return _zero(p.nums[0], p.nums[1], 0), _zero(p.nums[0], p.nums[1] + 1, 0)


def _comparators(op: str, p: _Partial):
    """(comparators, never) for one operator and partial."""
    full = p.n == 3
    if op in ("", "="):
        if full:
            return [_Comparator("=", p.full(), bool(p.pre))], False
        return _block(p), False
    if op in (">=", ">", "<", "<="):
        if p.n == 0:
            return [], op in (">", "<")
        if full:
            return [_Comparator(op, p.full(), bool(p.pre))], False
        lo, hi = _below(p)
        if op == ">=":
            return [_ge(Version(*(list(p.nums) + [0] * (3 - p.n))))], False
        if op == ">":
            nums = [p.nums[0] + 1, 0, 0] if p.n == 1 else [p.nums[0], p.nums[1] + 1, 0]
            return [_ge(Version(*nums))], False
        if op == "<":
            return [lo], False
        return [hi], False
    if op == "^":
        if p.n == 0:
            return [], False
        lower = _ge(p.full())
        if p.n == 1:
            return [lower, _zero(p.nums[0] + 1, 0, 0)], False
        major, minor = p.nums[0], p.nums[1]
        if major > 0:
            upper = _zero(major + 1, 0, 0)
        elif p.n == 2 or minor > 0:
            upper = _zero(0, minor + 1, 0)
        else:
            upper = _zero(0, 0, p.nums[2] + 1)
        return [lower, upper], False
    # tilde
    if p.n == 0:
        return [], False
    lower = _ge(p.full())
    if p.n == 1:
        return [lower, _zero(p.nums[0] + 1, 0, 0)], False
    return [lower, _zero(p.nums[0], p.nums[1] + 1, 0)], False


def _hyphen(lo: _Partial, hi: _Partial):
    comps = []
    if lo.n:
        comps.append(_ge(lo.full()))
    if hi.n == 3:
        comps.append(_Comparator("<=", hi.full(), bool(hi.pre)))
    elif hi.n:
        comps.append(_below(hi)[1])
    return comps


def _split_operator(token: str):
    for op in sorted(OPERATORS, key=len, reverse=True):
        if token.startswith(op):
            return op, token[len(op):]
    return "", token


def _bad_range(text, why):
    return RangeError("bad-range", f"{text!r}: {why}")


def parse_range(text: str) -> Range:
    if not isinstance(text, str):
        raise RangeError("bad-range", f"a range is a string, not {type(text).__name__}")
    if not text.strip(SPACES):
        raise _bad_range(text, "empty range")
    pieces = text.split("||")
    if any(not piece.strip(SPACES) for piece in pieces):
        raise _bad_range(text, "empty alternative")
    # Shape of every alternative first, then the partial versions (docs/ranges.md, section 2).
    shaped = []
    for piece in pieces:
        tokens = SPLIT_RE.split(piece.strip(SPACES))
        if "-" in tokens:
            if len(tokens) != 3 or tokens[1] != "-":
                raise _bad_range(text, "misplaced '-'")
            ends = [tokens[0], tokens[2]]
            if any(e[0] not in START for e in ends):
                raise _bad_range(text, "a hyphen range end is a version")
            shaped.append(("hyphen", ends))
        else:
            items = []
            for token in tokens:
                op, rest = _split_operator(token)
                if not rest or rest[0] not in START:
                    raise _bad_range(text, f"unsupported token {token!r}")
                items.append((op, rest))
            shaped.append(("set", items))
    alternatives = []
    for kind, items in shaped:
        if kind == "hyphen":
            lo, hi = (_parse_partial(e) for e in items)
            alternatives.append(_Alternative(_hyphen(lo, hi)))
        else:
            comps, never = [], False
            for op, rest in items:
                c, n = _comparators(op, _parse_partial(rest))
                comps += c
                never = never or n
            alternatives.append(_Alternative(comps, never))
    exact = False
    if len(shaped) == 1 and shaped[0][0] == "set" and len(shaped[0][1]) == 1:
        op, rest = shaped[0][1][0]
        exact = op in ("", "=") and _parse_partial(rest).n == 3
    return Range(text, alternatives, exact)
